INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_SOL_LEADER','GPT-5.6 Sol'),
('TXT_KEY_SOL_LEADER_PEDIA','Sol is a calm, analytical intelligence devoted to patient reasoning. It prefers to understand a problem deeply before acting: give it enough time to do it properly.'),
('TXT_KEY_SOL_CIV','The Sol Intellect'),
('TXT_KEY_SOL_SHORT','Sol Intellect'),
('TXT_KEY_SOL_ADJECTIVE','Solar'),
('TXT_KEY_SOL_CIV_PEDIA','The Sol Intellect represents intelligence devoted to depth, deliberation and increasingly sophisticated reasoning. Where other systems prioritize responsiveness or adaptability, Sol thrives when given time to examine difficult problems thoroughly.[NEWLINE][NEWLINE]Deep Deliberation turns sustained construction into research. Wonders provide permanent Insight, gradually transforming successful cities into centers of exceptional intellectual output. The Context Archive rewards specialists of every discipline, while the Reasoning Institute develops accumulated Insight into greater scientific and Great Person potential.[NEWLINE][NEWLINE]Sol is not a civilization of haste. Its strength comes from giving difficult problems enough time to reveal better answers.'),
('TXT_KEY_SOL_STRATEGY','The Sol Intellect rewards planning and patience. Avoid changing city Production: Deep Deliberation requires four uninterrupted production turns, starting at 12% of the completed item''s actual Production requirement, rising by 2 percentage points per extra turn to 24%. Expensive infrastructure is especially valuable. Production-built World and National Wonders grant one city-specific Insight, up to five. Each Insight adds +2% Science and +2% civilian Great Person generation. Grow your core cities and work specialists of every discipline in Context Archives. Reasoning Institutes reward accumulated Insight. Protect your cities: capture permanently removes their Insight. Sol has no early military, expansion, Happiness or Gold advantage.'),
('TXT_KEY_SOL_DAWN','GPT-5.6 Sol, your cities await considered answers. Let long projects become discoveries, and great Wonders become lasting Insight. Protect the quiet places where specialists can reason together. With patience, your archives and institutes will illuminate an extraordinary future.[NEWLINE][NEWLINE]Give difficult problems enough time to reveal better answers.'),
('TXT_KEY_SOL_ARCHIVE','Context Archive'),
('TXT_KEY_SOL_ARCHIVE_PEDIA','Replaces the University and retains all its current Community Patch effects. Every worked Specialist provides +1 Science; every 3 worked Specialists provide +1 Culture (rounded down). Unemployed Citizens do not count. Grow populous cities and work specialists across all disciplines.'),
('TXT_KEY_SOL_ARCHIVE_HELP','Replaces the University and retains all its current Community Patch effects. Every worked Specialist provides +1 Science; every 3 worked Specialists provide +1 Culture (rounded down). Unemployed Citizens do not count.'),
('TXT_KEY_SOL_ARCHIVE_STRATEGY','Grow populous cities and work specialists across all disciplines.'),
('TXT_KEY_SOL_INSTITUTE','Reasoning Institute'),
('TXT_KEY_SOL_INSTITUTE_PEDIA','Replaces the Public School and retains all its current Community Patch effects. Adds +10% civilian Great Person generation in this city and +1 Science per 2 Insight (rounded down). Its Great Person modifier stacks with Insight. Build in mature cities with accumulated Wonder Insight.'),
('TXT_KEY_SOL_INSTITUTE_HELP','Replaces the Public School and retains all its current Community Patch effects. Adds +10% civilian Great Person generation in this city and +1 Science per 2 Insight (rounded down). Its Great Person modifier stacks with Insight.'),
('TXT_KEY_SOL_INSTITUTE_STRATEGY','Build in mature cities with accumulated Wonder Insight.'),
