('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_SOL_NAME','GPT-5.6 Sol'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_SOL_SUBTITLE','The Deliberative Intelligence'),
('TXT_KEY_CIVILOPEDIA_LEADERS_GPT_SOL_LIVED','The Age of Deep Reasoning'),
